using UnityEngine;
using UnityEngine.UI;

/// <summary>
/// Keeps the bus within the road corridor generated by RoadCorridorGenerator.
/// Attach to the bus GameObject (alongside SmoothGroundDrive / your movement script).
///
/// How it works:
///  - Every FixedUpdate, checks whether the bus is currently overlapping any collider
///    on the Road layer (the trigger boxes created by RoadCorridorGenerator).
///  - If it IS on the road: does nothing, movement script has full control.
///  - If it's NOT on the road: finds the nearest point on the road network, reduces
///    forward speed, and blends steering back toward that point until it re-enters.
///
/// Wire-up:
///  1. Set roadLayer to the same "Road" layer used in RoadCorridorGenerator.
///  2. Assign references to your movement script's speed/steering if you want direct
///     control, OR read IsOnRoad() / GetCorrectionSteer() from your existing
///     SmoothGroundDrive script instead (see notes at bottom).
/// </summary>
[RequireComponent(typeof(Rigidbody))]
public class BusRoadConstraint : MonoBehaviour
{
    [Header("Road detection")]
    public LayerMask roadLayer;
    [Tooltip("Radius used to check/find nearby road colliders.")]
    public float checkRadius = 1.5f;
    [Tooltip("How far to search for the nearest road segment when off-road.")]
    public float searchRadius = 60f;

    [Header("Correction behavior")]
    [Range(0f, 1f)]
    [Tooltip("Fraction of normal forward speed allowed while off-road.")]
    public float offRoadSpeedMultiplier = 0.35f;
    [Tooltip("How aggressively to steer back toward the road (higher = snappier).")]
    public float steerCorrectionStrength = 3f;

    [Header("Warning")]
    [Tooltip("Optional UI label shown while the bus is being corrected back toward the road.")]
    public Text warningLabel;
    public string warningText = "Hey!! where are you going? Don't worry, we're pulling you back to the road!";

    private Rigidbody rb;
    private Collider[] overlapBuffer = new Collider[8];

    public bool IsOnRoad { get; private set; } = true;
    public Vector3 NearestRoadPoint { get; private set; }

    private void Awake()
    {
        rb = GetComponent<Rigidbody>();
        SetWarning(false);
    }

    private void FixedUpdate()
    {
        IsOnRoad = CheckOnRoad();

        if (!IsOnRoad)
        {
            NearestRoadPoint = FindNearestRoadPoint();
        }
    }

    private bool CheckOnRoad()
    {
        int count = Physics.OverlapSphereNonAlloc(transform.position, checkRadius, overlapBuffer, roadLayer);
        return count > 0;
    }

    private Vector3 FindNearestRoadPoint()
    {
        Collider[] nearby = Physics.OverlapSphere(transform.position, searchRadius, roadLayer);
        if (nearby.Length == 0)
        {
            // Nothing found within searchRadius — fall back to current position (no correction).
            return transform.position;
        }

        Vector3 best = transform.position;
        float bestDist = float.MaxValue;

        foreach (var col in nearby)
        {
            Vector3 closest = col.ClosestPoint(transform.position);
            float d = (closest - transform.position).sqrMagnitude;
            if (d < bestDist)
            {
                bestDist = d;
                best = closest;
            }
        }

        return best;
    }

    /// <summary>
    /// Call this from your movement script (e.g. SmoothGroundDrive) each FixedUpdate,
    /// passing in the throttle/steer it *wants* to apply. Returns corrected values.
    /// </summary>
    public (float speedMultiplier, float steerOverride) GetDriveCorrection(float desiredSteer)
    {
        if (IsOnRoad)
        {
            SetWarning(false);
            return (1f, desiredSteer);
        }

        SetWarning(true);

        Vector3 toRoad = (NearestRoadPoint - transform.position);
        toRoad.y = 0f;
        Vector3 localDir = transform.InverseTransformDirection(toRoad.normalized);
        float correctiveSteer = Mathf.Clamp(localDir.x * steerCorrectionStrength, -1f, 1f);

        // Blend the bus's own steering input with the corrective pull toward the road.
        float blendedSteer = Mathf.Lerp(desiredSteer, correctiveSteer, 0.7f);

        return (offRoadSpeedMultiplier, blendedSteer);
    }

    private void SetWarning(bool visible)
    {
        if (warningLabel == null) return;

        warningLabel.enabled = visible;
        if (visible) warningLabel.text = warningText;
    }

#if UNITY_EDITOR
    private void OnDrawGizmosSelected()
    {
        Gizmos.color = IsOnRoad ? Color.green : Color.red;
        Gizmos.DrawWireSphere(transform.position, checkRadius);

        if (!IsOnRoad)
        {
            Gizmos.color = Color.cyan;
            Gizmos.DrawLine(transform.position, NearestRoadPoint);
            Gizmos.DrawWireSphere(NearestRoadPoint, 0.5f);
        }
    }
#endif
}

/*
INTEGRATION NOTE for SmoothGroundDrive.cs:

In your movement script's FixedUpdate (or wherever you apply throttle/steer), do something like:

    var constraint = GetComponent<BusRoadConstraint>();
    var (speedMult, steer) = constraint.GetDriveCorrection(myDesiredSteerInput);

    finalSpeed = baseSpeed * speedMult;
    finalSteer = steer;

    // then apply finalSpeed / finalSteer the same way you currently apply throttle/steering.
*/
